/* Fichier généré par tools/build.py à partir de data/lessons/*.json — ne pas modifier à la main. */
window.LESSONS = {"autoroute":{"theme":"autoroute","title":"L'autoroute et les routes pour automobiles","intro":"Sur l'autoroute, tout va vite : une erreur se paie cher. L'examen adore les pièges sur qui peut y entrer, la bande d'arrêt d'urgence et le couloir de secours. Retiens les quelques chiffres clés et tu gagnes des points faciles.","sections":[{"title":"Où commence et où finit l'autoroute","body":"<p>Les règles spéciales de l'autoroute s'appliquent <b>dès l'endroit où le signal F5</b> est placé (début ou accès d'autoroute). Elles cessent au signal <b>F7</b> (fin d'autoroute).</p><ul><li>Tu entres et tu sors <b>uniquement aux endroits aménagés</b> (bretelles d'accès et de sortie).</li><li>Le signal <b>F9</b> annonce une <b>route pour automobiles</b> : une route rapide, avec des règles très proches de l'autoroute (voir plus bas).</li></ul>","signs":["F5","F7","F9"],"tip":"F5 = début, F7 = fin. Les règles s'appliquent à partir du panneau, pas à partir de la première bande de circulation.","ref":"Art. 2.3, 21.1 et 71 AR 01/12/1975"},{"title":"Qui n'a pas le droit d'y aller ?","body":"<p>L'accès à l'autoroute est <b>interdit</b> :</p><ul><li>aux <b>piétons</b>, <b>cyclistes</b>, <b>cyclomoteurs</b> et conducteurs d'<b>animaux</b> ;</li><li>aux véhicules qui ne peuvent pas atteindre <b>70 km/h en palier</b> (sur route plate) ;</li><li>aux <b>quadricycles à moteur sans habitacle</b> (quads) ;</li><li>aux <b>véhicules agricoles</b> (même pour 2 km) ;</li><li>à un véhicule qui en <b>remorque un autre avec une attache de fortune</b> (corde, sangle…).</li></ul><p>Ta voiture est en panne ? Ton ami ne peut pas la tirer à la corde sur l'autoroute : appelle une dépanneuse.</p>","signs":["F5"],"tip":"Pense « trop lent ou trop fragile » : piétons, vélos, cyclos, animaux, tracteurs, quads, et tout ce qui ne fait pas 70 km/h.","ref":"Art. 21.1 AR 01/12/1975"},{"title":"Les vitesses : maximum 120, minimum 70","body":"<p>Sur autoroute, la vitesse maximale est de <b>120 km/h</b>, dans les trois Régions.</p><ul><li>Les véhicules de <b>plus de 3,5 t</b> et les autobus : <b>90 km/h</b>.</li><li><b>Vitesse minimale : 70 km/h</b>. Exception : un signal <b>C43</b> impose une limite plus basse (par ex. 50 km/h à un chantier) ; tu peux alors rouler en dessous de 70.</li><li>Tu dois toujours <b>adapter ta vitesse</b> : brouillard, pluie, bouchon… Le minimum de 70 ne t'oblige pas à foncer dans le brouillard.</li></ul><p><b>Route pour automobiles (F9)</b> : pas de vitesse minimale. Maximum <b>120 km/h</b> si elle a 2 bandes par sens séparées autrement que par des marques au sol (terre-plein, glissière). Sinon, c'est la limite hors agglomération de la Région : <b>90 km/h en Wallonie</b>, <b>70 km/h en Flandre</b> (et à Bruxelles), sauf C43.</p>","signs":["C43-120","C43-50"],"tip":"Piège classique : « je roule à 50 sur autoroute au chantier, est-ce permis ? » Oui, si un C43 l'impose.","ref":"Art. 11.2 et 21.2 AR 01/12/1975"},{"title":"Entrer, rouler, dépasser","body":"<ul><li><b>Insertion</b> : sur la bande d'accélération, prends de la vitesse, mets ton clignotant et <b>cède le passage</b> à ceux qui roulent déjà sur l'autoroute. Changer de bande est une manœuvre.</li><li><b>Garde ta droite</b> : même si les bandes du milieu et de gauche sont libres, tu roules sur la bande de droite. Après un dépassement, reviens à droite dès que possible.</li><li><b>On dépasse par la gauche</b>. Une voiture lente sur la bande de gauche ? Tu ne la dépasses pas par la droite.</li><li><b>Exception : la circulation en files</b>. Quand c'est dense et que tout le monde roule en files, une file qui avance plus vite que l'autre, ce n'est pas un dépassement.</li><li>Autoroute à <b>3 bandes ou plus</b> : les camions de plus de <b>3,5 t</b>, bus et autocars ne peuvent utiliser que les <b>deux bandes de droite</b>.</li></ul>","tip":"« Dépasser par la droite » est interdit, mais « la file de droite avance plus vite » dans un trafic dense ne l'est pas.","ref":"Art. 9.3.1, 9.5, 12.4, 13, 16 et 21.3 AR 01/12/1975"},{"title":"La tirette : se rabattre juste devant le rétrécissement","body":"<p>Une bande se termine (travaux, accident) et la circulation est <b>fortement ralentie</b> ? Tu restes sur ta bande jusqu'au bout et tu t'intercales <b>juste devant le rétrécissement</b>.</p><p>Ceux qui roulent sur la bande libre laissent passer <b>tour à tour</b> une voiture qui s'insère. Comme une fermeture éclair : un de chaque côté.</p>","tip":"Se rabattre trop tôt n'est pas « plus poli » : la règle, c'est juste devant le rétrécissement, une voiture sur deux.","ref":"Art. 12bis AR 01/12/1975"},{"title":"Interdit sur l'autoroute (et sur la route pour automobiles)","body":"<ul><li>Faire <b>demi-tour</b>.</li><li>Faire <b>marche arrière</b> ou rouler en <b>sens contraire</b>. Sortie manquée ? Tu continues jusqu'à la suivante.</li><li>Emprunter les <b>raccordements transversaux</b> (passages dans le terre-plein central) : réservés aux secours et à l'entretien.</li><li>T'<b>arrêter ou stationner</b>, sauf sur les <b>aires de stationnement</b> signalées par <b>E9a</b>. Fatigué ? Va jusqu'à l'aire. Un coup de téléphone n'est pas une raison de t'arrêter.</li><li><b>Remorquer</b> avec une attache de fortune.</li></ul><p>Ces interdictions valent aussi sur les <b>routes pour automobiles</b> (F9). Sur une route pour automobiles, même s'il y a une interruption du terre-plein, pas de demi-tour.</p>","signs":["E9a","F9"],"tip":"Sur une route pour automobiles, les cyclos, véhicules agricoles, trains forains et quads sont aussi interdits.","ref":"Art. 21.4, 22.1 et 22.2 AR 01/12/1975"},{"title":"Bande d'arrêt d'urgence et couloir de secours","body":"<p><b>Bande d'arrêt d'urgence</b> : interdit d'y rouler, même pour atteindre ta sortie dans un bouchon. Seuls peuvent l'utiliser :</p><ul><li>les <b>véhicules prioritaires</b> en mission urgente ;</li><li>les services requis par la police ou le parquet, et les <b>dépanneuses</b>, pour aller sur le lieu d'un incident quand le trafic est fortement ralenti ou arrêté.</li></ul><p><b>Couloir de secours</b> : à former <b>dès qu'une file se forme</b>, sans attendre d'entendre les sirènes.</p><ul><li><b>2 bandes</b> : bande de gauche → serre à gauche ; bande de droite → serre à droite.</li><li><b>3 bandes ou plus</b> : bande de gauche → serre à gauche ; <b>toutes les autres → serrent à droite</b>. Le couloir se trouve à côté de la bande de gauche.</li></ul><p>Le couloir est réservé aux secours et aux dépanneuses : tu ne l'empruntes jamais pour avancer.</p>","tip":"Gauche à gauche, tous les autres à droite. Tu es au milieu sur 3 bandes ? Tu serres à droite.","ref":"Art. 2.70, 9.7 et 9.8 AR 01/12/1975"},{"title":"En panne sur l'autoroute","body":"<ol><li>Range-toi sur la <b>bande d'arrêt d'urgence</b> et allume tes <b>feux de détresse</b>.</li><li>Enfile ta <b>veste de sécurité rétroréfléchissante</b> <b>avant</b> de sortir (de jour comme de nuit).</li><li>Place le <b>triangle de danger</b> à au moins <b>100 m</b> derrière la voiture (30 m sur les routes ordinaires), visible à environ 50 m.</li></ol><p>Les feux de détresse ne <b>remplacent pas</b> le triangle : il est obligatoire quand ton véhicule est immobilisé là où l'arrêt est interdit.</p>","tip":"100 m sur autoroute, 30 m ailleurs. Veste dès que tu sors : obligatoire sur autoroute et route pour automobiles.","ref":"Art. 51.1, 51.2 et 51.4 AR 01/12/1975"},{"title":"Les signaux lumineux au-dessus des bandes","body":"<ul><li><b>Croix rouge</b> : bande interdite. Quitte-la prudemment.</li><li><b>Flèche verte</b> pointée vers le bas : tu peux rouler sur cette bande.</li><li><b>Flèche orange oblique</b> (parfois clignotante) : bande interdite, sauf pour la <b>quitter dans le sens de la flèche</b>.</li></ul><p>Les véhicules prioritaires et dépanneuses en intervention peuvent quand même utiliser une bande fermée.</p>","tip":"Rouge = interdit, vert = autorisé, orange oblique = « dégage dans la direction de la flèche ».","ref":"Art. 62bis AR 01/12/1975"}],"keypoints":["Règles de l'autoroute dès le F5, jusqu'au F7.","Interdit : piétons, vélos, cyclos, animaux, tracteurs, quads, véhicules < 70 km/h, remorquage à la corde.","Maximum 120 km/h, minimum 70 km/h (sauf C43 plus bas).","Toujours à droite ; dépassement par la gauche, sauf circulation en files.","Jamais de demi-tour, marche arrière ni arrêt (sauf aire E9a) ; idem sur route pour automobiles.","Couloir de secours dès la file : gauche à gauche, tous les autres à droite.","Panne : veste avant de sortir, triangle à 100 m (30 m ailleurs).","Croix rouge = bande fermée ; flèche orange = quitte la bande."]},"depassement":{"theme":"depassement","title":"Place sur la route, croisement et dépassement","intro":"Dépasser est une des manœuvres les plus dangereuses : un mauvais dépassement, c'est souvent un choc frontal. À l'examen, on te teste sur où te placer, quand tu peux dépasser, quand c'est interdit, et comment partager la route avec les cyclistes. Les règles sont logiques : si tu ne vois pas, tu ne dépasses pas.","sections":[{"title":"Ta place sur la chaussée","body":"<p>Règle de base : tu roules sur la chaussée, <b>le plus près possible du bord droit</b>. Exceptions :</p><ul><li>sur les places, ou si des flèches au sol (signaux F13/F15) t'indiquent une bande ;</li><li>dans l'<b>anneau d'un rond-point</b> : tu n'es pas obligé de serrer à droite, mais tu respectes les bandes marquées et tu prends celle qui convient le mieux à ta destination ;</li><li>en <b>agglomération</b>, sur une chaussée à sens unique en bandes ou à 2 × 2 bandes minimum, tu peux choisir la bande qui convient le mieux à ta destination.</li></ul><p>Si la route a <b>deux ou trois chaussées nettement séparées</b> (terre-plein), tu n'empruntes <b>jamais celle de gauche</b> (sauf réglementation locale) : ce serait rouler à contresens.</p><p>Bornes et îlots directionnels : tu les laisses <b>à ta gauche</b>, sauf si un panneau D1 t'indique un autre côté.</p>","signs":["D5","D1-downright"],"tip":"Rond-point : pas d'obligation de serrer à droite dans l'anneau, mais les lignes de bande restent à respecter.","ref":"Art. 9.1 à 9.6 AR 01/12/1975"},{"title":"Autoroute : couloir de secours et bande d'arrêt d'urgence","body":"<p>Un bouchon se forme ? Tu crées tout de suite un <b>couloir de secours</b> pour les secours :</p><ul><li><b>2 bandes</b> : bande de gauche serre à gauche, bande de droite serre à droite. Le couloir est au milieu.</li><li><b>Plus de 2 bandes</b> : seule la <b>bande de gauche serre à gauche</b>, <b>toutes les autres serrent à droite</b>. Le couloir se forme à côté de la bande de gauche.</li></ul><p>La <b>bande d'arrêt d'urgence</b> est interdite à la circulation, même dans un bouchon pour atteindre la sortie. Seuls y roulent : véhicules prioritaires en mission urgente, services requis par la police ou le parquet, dépanneuses (pour un incident, en cas de forte congestion).</p><p>Sur autoroute, il est aussi interdit de faire <b>demi-tour</b>, <b>marche arrière</b> ou de rouler à contresens. Sortie ratée ? Tu continues jusqu'à la suivante.</p>","signs":["F5"],"tip":"Couloir de secours : « la gauche à gauche, tout le reste à droite ».","ref":"Art. 9.7, 9.8 et 21.4 AR 01/12/1975"},{"title":"Le croisement","body":"<p>Un véhicule arrive en face. Le <b>croisement se fait à droite</b> :</p><ul><li>tu laisses une <b>distance latérale suffisante</b> et, au besoin, tu serres à droite ;</li><li>si la chaussée est trop étroite, tu peux utiliser l'<b>accotement de plain-pied</b> (ou la bande latérale), sans mettre en danger ceux qui s'y trouvent.</li></ul><p>Un obstacle (camionnette garée, travaux) est <b>sur ta moitié</b> de chaussée ? C'est <b>toi</b> qui ralentis et, au besoin, t'arrêtes pour laisser passer ceux d'en face.</p>","tip":"Obstacle de ton côté = tu laisses passer. Obstacle de leur côté = ils doivent te laisser passer.","ref":"Art. 15 AR 01/12/1975"},{"title":"Comment dépasser correctement","body":"<p>Le <b>dépassement se fait à gauche</b>. Une seule exception : tu dépasses <b>par la droite</b> quand le conducteur devant a <b>annoncé qu'il tourne (ou se range) à gauche</b> et <b>s'est porté à gauche</b>. Une voiture lente sans clignoteur au milieu de sa bande ? Toujours par la gauche.</p><p>Avant de te déporter, vérifie que :</p><ol><li>la voie est libre sur une distance suffisante ;</li><li><b>personne derrière toi n'a commencé à te dépasser</b> (rétro + angle mort) ;</li><li>tu pourras reprendre ta place à droite sans gêner ;</li><li>le dépassement se fera <b>en un temps très court</b>.</li></ol><p>Puis : <b>clignoteur gauche</b>, tu t'écartes assez, et tu reviens à droite <b>dès que possible sans inconvénient</b>, avec ton <b>clignoteur droit</b>.</p><p>Sur une chaussée à <b>sens unique</b> (ex. autoroute) ou à 2 × 2 bandes minimum, tu peux rester à gauche pour enchaîner <b>aussitôt</b> un autre dépassement.</p><p><b>Tu te fais dépasser ?</b> Tu serres à droite et tu <b>n'accélères pas</b>.</p>","tip":"Ordre des vérifications : devant, derrière (rétro + angle mort), clignoteur, puis seulement tu déboîtes.","ref":"Art. 16 AR 01/12/1975"},{"title":"Quand il est interdit de dépasser","body":"<p>Toujours interdit si tu <b>ne vois pas assez loin</b> les véhicules d'en face. Et interdit de dépasser par la gauche une voiture, une moto ou un véhicule attelé :</p><ul><li>à l'<b>approche d'un sommet de côte</b> ou dans un <b>virage</b> sans visibilité suffisante (sauf si tu restes sans franchir la ligne continue) ;</li><li>dans un <b>carrefour à priorité de droite</b> ;</li><li>dans les autres carrefours, <b>si tu dois céder le passage</b> (B1, B5, sortie d'un chemin de terre). Sur la route prioritaire (B9), le carrefour seul n'interdit pas le dépassement, s'il se fait sans danger ;</li><li>quand le véhicule devant <b>approche ou s'arrête devant un passage pour piétons ou cyclistes</b> non réglé par feux ou agent : il cache peut-être quelqu'un ;</li><li>sur un <b>passage à niveau</b> sans barrières ni feux (croix de Saint-André) ;</li><li>quand le véhicule devant <b>dépasse lui-même</b> (autre chose qu'un vélo, cyclomoteur ou moto à deux roues), sauf s'il y a au moins 3 bandes dans ton sens ;</li><li>sur un <b>dispositif surélevé</b> (ralentisseur).</li></ul><p>Et bien sûr : <b>jamais franchir une ligne continue</b>.</p>","signs":["B17","B1","B5","B9"],"tip":"Retiens « je ne vois pas, je ne dépasse pas » : côte, virage, passage piétons, carrefour où tu n'es pas prioritaire.","ref":"Art. 17 et 72.2 AR 01/12/1975"},{"title":"Le panneau « interdiction de dépasser »","body":"<p>Le panneau <b>C35</b> interdit de dépasser par la gauche un <b>véhicule attelé ou un véhicule à plus de deux roues</b> (voitures, camions…).</p><ul><li>Il vaut <b>jusqu'au prochain carrefour inclus</b>, ou jusqu'au panneau de fin <b>C37</b>.</li><li>Il ne vise <b>pas les deux-roues</b> : tu peux dépasser un cycliste ou une moto, sans danger et en respectant la distance latérale.</li></ul><p>Le <b>C46</b> met fin à toutes les interdictions locales, y compris celle-ci.</p>","signs":["C35","C46"],"tip":"C35 : une voiture rouge à côté d'une noire. Pas de vélo dessus, donc le vélo peut être dépassé.","ref":"Art. 68 (C35, C37, C46) AR 01/12/1975"},{"title":"Dépasser un cycliste","body":"<p>Le cycliste est fragile : un écart, un coup de vent, et il est sur ta trajectoire. Distance latérale minimale quand tu le dépasses :</p><ul><li><b>en agglomération : 1 mètre</b> ;</li><li><b>hors agglomération : 1,5 mètre</b>.</li></ul><p>Même règle pour les cyclomoteurs à deux roues. Redouble de prudence avec les enfants et les personnes âgées à vélo.</p><p>Les interdictions de dépasser dans les carrefours ne visent pas les vélos. Mais tu dois toujours dépasser sans danger.</p><p>Route étroite, <b>ligne continue</b> au milieu, impossible de laisser 1,5 m sans la franchir ? Tu <b>restes derrière</b> le cycliste jusqu'à pouvoir dépasser correctement.</p>","tip":"1 m en ville, 1,5 m hors ville. Pas la place ? Patience, tu restes derrière.","ref":"Art. 40ter, 17.2 et 72.2 AR 01/12/1975"},{"title":"Changer de direction et manœuvrer","body":"<p>Avant de tourner, tu vérifies que tu peux le faire sans danger (pense à ceux qui te suivent), et tu mets ton <b>clignoteur à temps</b>.</p><p><b>Tourner à droite</b> : clignoteur droit, tu <b>serres le bord droit</b>, allure modérée, virage court.</p><p><b>Tourner à gauche</b> :</p><ul><li>chaussée à deux sens : tu te portes vers la gauche sans gêner ceux d'en face, et tu <b>leur cèdes le passage</b> ;</li><li>chaussée à <b>sens unique</b> : tu <b>serres le bord gauche</b>.</li></ul><p>En bandes ou en files : on ne tourne à droite que <b>depuis la bande de droite</b>, et à gauche que depuis celle de gauche.</p><p>En tournant, tu cèdes le passage aux piétons qui traversent et aux usagers (cyclistes…) qui circulent sur les autres parties de la voie.</p><p><b>Manœuvres</b> (marche arrière, demi-tour, sortir d'une allée ou d'une place de parking, changer de bande) : celui qui manœuvre <b>cède le passage à tous</b>.</p>","signs":["F19"],"tip":"Rond-point : pas de clignoteur pour y entrer, clignoteur droit pour en sortir.","ref":"Art. 12.4, 13 et 19 AR 01/12/1975"},{"title":"La tirette (fermeture éclair)","body":"<p>Bouchon, ta bande se termine plus loin (travaux, rétrécissement). Que faire ?</p><ul><li>Si la circulation est <b>fortement ralentie</b> : tu restes sur ta bande et tu t'intercales <b>seulement juste devant le rétrécissement</b>.</li><li>Ceux de la bande qui continue laissent passer <b>tour à tour</b> un conducteur qui s'intercale, juste devant le rétrécissement. Un de chaque côté, comme une fermeture éclair.</li><li>Si les deux bandes extérieures se terminent : priorité d'abord à celui de droite, puis à celui de gauche.</li></ul><p>Si la circulation est <b>fluide</b>, pas de tirette : changer de bande est une <b>manœuvre</b>, et c'est toi qui cèdes le passage.</p>","signs":["A7a"],"tip":"Tirette = seulement quand ça bouchonne, et seulement au bout de la bande. Se rabattre trop tôt n'est pas « plus poli » : ça allonge le bouchon.","ref":"Art. 12bis et 12.4 AR 01/12/1975"}],"keypoints":["Tiens-toi le plus près possible du bord droit (sauf dans l'anneau d'un rond-point).","Couloir de secours : la bande de gauche serre à gauche, toutes les autres à droite. Bande d'arrêt d'urgence interdite.","Obstacle de ton côté : tu laisses passer ceux d'en face.","Dépassement à gauche ; à droite seulement si l'autre tourne à gauche et s'est porté à gauche.","Interdit de dépasser : côte ou virage sans visibilité, carrefour à priorité de droite, avant un passage piétons, ligne continue.","C35 : interdit de dépasser les véhicules à plus de 2 roues, jusqu'au prochain carrefour inclus.","Cycliste : 1 m en agglomération, 1,5 m hors agglomération.","Tirette : seulement en circulation fortement ralentie, juste devant le rétrécissement, tour à tour."]},"priorite":{"theme":"priorite","title":"Priorités, carrefours et manœuvres","intro":"Les questions de priorité sont parmi les plus fréquentes à l'examen, et beaucoup sont des fautes graves. Une erreur de priorité au carrefour, c'est l'accident assuré. Bonne nouvelle : avec quelques règles simples et dans le bon ordre, tu peux répondre à presque tout.","sections":[{"title":"La règle de base : la priorité de droite","body":"<p>Tu arrives à un carrefour sans panneau, sans feu, sans agent ? Tu cèdes le passage à celui qui vient de <b>ta droite</b>. Peu importe la largeur de la route ou la vitesse de l'autre.</p><ul><li>Une voiture arrive de ta gauche ? C'est elle qui doit te céder le passage. Mais tu restes prudent : à un carrefour, tu dois toujours <b>redoubler de prudence</b>.</li><li>Le panneau <b>B17</b> (triangle avec une croix) annonce justement un carrefour où la priorité de droite s'applique.</li></ul><p><b>Deux exceptions</b> : la priorité de droite ne joue pas pour celui qui</p><ul><li>circule <b>dans un rond-point</b> ;</li><li>vient d'un <b>sens interdit</b> (il roule à contresens : il n'a pas la priorité, mais tu évites quand même l'accident).</li></ul><p><b>Chemin de terre</b> : si tu sors d'un chemin de terre ou d'un sentier pour t'engager sur une route avec chaussée, tu cèdes le passage à <b>tout le monde</b>, de droite comme de gauche.</p>","signs":["B17"],"tip":"Piège classique : « je suis sur la route la plus large » ou « je roule plus vite ». Ça ne compte jamais. Seule la droite compte.","ref":"Art. 12.2 et 12.3.1 AR 01/12/1975"},{"title":"Les panneaux de priorité","body":"<p>Les panneaux passent avant la priorité de droite. Connais-les par cœur :</p><ul><li><b>B1 – Cédez le passage</b> (triangle pointe en bas) : tu cèdes à <b>tous</b> les conducteurs de la route que tu abordes, de gauche comme de droite. Si personne n'arrive, tu peux continuer sans t'arrêter. Au sol : une ligne de <b>triangles blancs</b> montre où t'arrêter s'il le faut.</li><li><b>B5 – Stop</b> (octogone rouge) : arrêt <b>obligatoire</b>, même si la route est vide et la visibilité parfaite. Tu t'arrêtes à la <b>ligne d'arrêt</b> (ligne blanche continue en travers), puis tu cèdes le passage.</li><li><b>B9 – Voie prioritaire</b> (losange jaune bordé de blanc) : tu as la priorité aux carrefours, même sur ceux qui viennent de droite.</li><li><b>B11 – Fin de voie prioritaire</b> (losange barré) : sans autre panneau, la priorité de droite revient.</li><li><b>B15 – Priorité de passage</b> : priorité au <b>prochain carrefour</b> seulement.</li><li><b>B19</b> (passage étroit) : tu cèdes le passage à ceux qui arrivent <b>en face</b>.</li><li><b>B21</b> (passage étroit, carré bleu) : <b>toi</b>, tu as la priorité sur ceux d'en face. Si l'autre est déjà engagé, reste prudent.</li></ul><p>Céder le passage, c'est ne repartir que si tu peux le faire <b>sans risque d'accident</b>, en tenant compte de la position, de la vitesse et de la distance des autres. Si c'est « juste », tu attends.</p>","signs":["B1","B5","B9","B11","B15","B19","B21"],"tip":"B1 = je cède, je m'arrête seulement si nécessaire. B5 = je m'arrête toujours, puis je cède. B19 rond à bord rouge = je cède ; B21 carré bleu = j'ai la priorité.","ref":"Art. 12.3.1, 12.5, 67.3, 76.1 et 76.2 AR 01/12/1975"},{"title":"Les ronds-points","body":"<p>Un rond-point, c'est une voirie à sens unique autour d'un îlot central, signalée par des panneaux <b>D5</b> (sens giratoire), avec des accès munis d'un <b>B1</b> ou d'un <b>B5</b>.</p><ul><li><b>Tu entres</b> : tu cèdes le passage à ceux qui sont déjà dans l'anneau (ils viennent de ta gauche).</li><li><b>Tu es dans l'anneau</b> : tu as la priorité, même sur une voiture qui veut entrer par ta droite.</li><li><b>Clignotant</b> : pas obligatoire pour <b>entrer</b>, mais <b>obligatoire pour sortir</b> (clignotant droit avant ta sortie).</li></ul>","signs":["D5","B1"],"tip":"Retiens « on entre sans clignoter, on sort en clignotant à droite ».","ref":"Art. 2.39, 12.3.1 et 19.2, 1° AR 01/12/1975"},{"title":"Les manœuvres : tu cèdes à tout le monde","body":"<p>Quand tu fais une <b>manœuvre</b>, tu dois céder le passage à <b>tous les autres usagers</b> (voitures, cyclistes, piétons). Sont des manœuvres :</p><ul><li>changer de bande ou de file ;</li><li>traverser la chaussée ;</li><li>quitter une place de stationnement ou y entrer ;</li><li>sortir d'une <b>propriété riveraine</b> (garage, parking de supermarché…) ;</li><li>faire un <b>demi-tour</b> ou une <b>marche arrière</b>.</li></ul><p>Le <b>clignotant</b> annonce la manœuvre, mais il ne te donne <b>aucune priorité</b>.</p><p>Tu traverses un <b>trottoir</b> ou une <b>piste cyclable</b> (sortie de garage) ? Tu cèdes le passage aux piétons et cyclistes qui y circulent.</p><p><b>Tirette</b> : quand le trafic est fortement ralenti et qu'une bande se termine, on s'insère <b>juste devant le rétrécissement</b>, une voiture sur deux.</p><p><b>Bus en agglomération</b> : quand un bus met son clignotant pour quitter son arrêt, tu ralentis et au besoin tu t'arrêtes pour le laisser partir.</p>","tip":"Tu sors d'un parking ou d'un garage ? Même une voiture qui vient de ta gauche passe avant toi.","ref":"Art. 12.4, 12.4bis, 12bis, 13 et 39 AR 01/12/1975"},{"title":"Tourner à gauche ou à droite","body":"<p>Quand tu changes de direction au carrefour, tu restes le « petit » face aux autres :</p><ul><li><b>Tu tournes à gauche</b> : tu cèdes le passage aux véhicules qui arrivent <b>en sens inverse</b> (même s'ils vont tout droit).</li><li><b>Tu tournes à droite</b> : tu cèdes le passage au cycliste qui continue tout droit sur la <b>piste cyclable</b> à ta droite. Regarde dans ton rétro et ton angle mort !</li><li>Dans les deux cas, tu cèdes le passage aux <b>piétons</b> qui traversent la rue où tu t'engages.</li></ul>","tip":"Tourner = céder : à ceux d'en face (à gauche), aux cyclistes tout droit (à droite), et toujours aux piétons.","ref":"Art. 19.3, 3°, 19.4 et 19.5 AR 01/12/1975"},{"title":"Trams et véhicules prioritaires","body":"<p><b>Le tram</b> (véhicule sur rails) passe <b>toujours</b> en premier, qu'il vienne de droite ou de gauche. Tu roules sur les rails et un tram arrive derrière toi ? Tu t'écartes <b>dès que possible</b>.</p><p><b>Véhicules prioritaires</b> (police, ambulance, pompiers…) : ils ont des feux bleus clignotants et une sirène (avertisseur sonore spécial).</p><ul><li>Dès que tu entends la <b>sirène</b>, tu dois <b>immédiatement dégager</b> et céder le passage ; au besoin, tu t'arrêtes.</li><li>Avec la sirène, il peut franchir un <b>feu rouge</b>, à vitesse modérée et sans mettre les autres en danger.</li><li>Feux bleus seuls, sans sirène ? L'obligation légale naît avec la sirène, mais reste très prudent et facilite-lui le passage.</li></ul>","tip":"La sirène crée l'obligation de dégager (art. 38). Le tram, lui, est prioritaire en permanence (art. 12.1).","ref":"Art. 12.1, 37 et 38 AR 01/12/1975"},{"title":"Agents, feux et carrefours encombrés","body":"<p>Retiens l'ordre de force : d'abord l'<b>agent</b>, puis la <b>signalisation</b> (feux, panneaux), puis les <b>règles</b> (comme la priorité de droite).</p><ul><li><b>Bras levé verticalement</b> : arrêt pour tous, sauf pour ceux déjà dans le carrefour, qui doivent l'<b>évacuer</b>.</li><li><b>Bras tendus horizontalement</b> : arrêt pour ceux dont la direction <b>coupe</b> celle des bras (tu arrives face à lui ou dans son dos).</li><li>Un <b>signaleur</b> (course cycliste, chantier…) qui te montre un disque <b>C3</b> : tu t'arrêtes.</li></ul><p><b>Feux et panneaux ensemble</b> : quand les feux fonctionnent, les panneaux de priorité sur la même voie (B1, B5…) sont <b>sans effet</b>. Feu vert = tu passes. Mais si le feu <b>orange clignote</b>, tu redoubles de prudence et les panneaux reprennent leur valeur (ou la priorité de droite s'il n'y en a pas).</p><p><b>Carrefour bloqué</b> : même au vert, tu ne t'engages pas si tu risques de rester coincé au milieu et de bloquer la circulation transversale. Si tu es déjà engagé, tu peux dégager le carrefour.</p>","signs":["FEU-vert","FEU-orange-cligno","C3"],"tip":"Orange clignotant = « débrouille-toi avec les panneaux » : il ne donne aucune priorité.","ref":"Art. 4.2, 6.1 à 6.3, 14, 41.3.2 et 64.1 AR 01/12/1975"}],"keypoints":["Sans signalisation : priorité de droite, quelle que soit la largeur de la route.","Pas de priorité de droite pour qui vient d'un sens interdit ou d'un chemin de terre, ni contre qui est dans le rond-point.","B5 (stop) : arrêt obligatoire à la ligne d'arrêt, même si la route est vide. B1 : arrêt seulement si nécessaire.","Rond-point : on cède pour entrer ; clignotant obligatoire seulement pour sortir.","Manœuvre (parking, garage, demi-tour, marche arrière) : tu cèdes à tout le monde.","Tram : toujours prioritaire. Sirène : dégager immédiatement, s'arrêter au besoin.","Agent, puis feux et panneaux, puis règles. Feux en marche = panneaux de priorité sans effet, sauf orange clignotant.","Même au vert, on ne s'engage pas dans un carrefour où l'on resterait bloqué."]},"securite":{"theme":"securite","title":"Sécurité : équipement, comportement et permis provisoire","intro":"Ce thème mélange plein de petites règles qui sauvent des vies : les feux, la ceinture, le GSM, l'alcool, la fatigue. À l'examen, ce sont souvent des fautes graves. Bonne nouvelle : avec quelques chiffres en tête, tu les réussis toutes.","sections":[{"title":"Les feux en roulant","body":"<p>Tu allumes tes feux <b>entre la tombée et le lever du jour</b>, et chaque fois que tu ne vois plus distinctement à environ <b>200 m</b> (grosse averse, brouillard…).</p><p><b>Feux de route → feux de croisement</b> :</p><ul><li>quand un usager arrive en face, assez tôt pour qu'il passe sans danger (et tout de suite s'il fait des appels de phares : il est ébloui) ;</li><li>quand tu suis un véhicule à <b>moins de 50 m</b> (sauf pendant un dépassement) ;</li><li>quand la route est éclairée de façon continue et que tu vois à environ <b>100 m</b>.</li></ul><p><b>Brouillard</b> :</p><ul><li>feux de brouillard <b>avant</b> : seulement par brouillard, neige ou forte pluie ;</li><li>feu de brouillard <b>arrière</b> : <b>obligatoire</b> (si ta voiture en a un) par brouillard ou neige avec visibilité <b>sous 100 m</b>, et par forte pluie. <b>Interdit</b> dans tous les autres cas : il éblouit ceux qui te suivent.</li></ul>","tip":"Les chiffres à retenir : 200 m (allumer), 100 m (brouillard arrière / route éclairée), 50 m (suivre quelqu'un).","ref":"Art. 30 AR 01/12/1975"},{"title":"Feux à l'arrêt, feux de détresse et bus scolaire","body":"<p><b>Stationné la nuit</b> sur une route non éclairée : feux de <b>position</b> à l'avant et feux <b>rouges</b> à l'arrière.</p><ul><li><b>En agglomération</b>, garé parallèlement à la chaussée et sans remorque : un seul <b>feu de stationnement</b> suffit, celui du <b>côté de la chaussée</b>.</li><li>Si l'éclairage public permet de voir ta voiture à environ <b>100 m</b>, ces feux ne sont pas obligatoires.</li></ul><p><b>Feux de détresse</b> (tous les clignotants) : seulement pour une <b>panne</b>, un <b>chargement tombé</b>, un <b>bus scolaire</b> qui fait monter ou descendre des enfants, ou un <b>risque d'accident imminent</b> (ex. bouchon soudain sur l'autoroute).</p><p>Un bus scolaire arrêté avec tous ses clignotants ? Des enfants montent ou descendent : <b>ralentis fortement</b> et arrête-toi si nécessaire.</p>","tip":"Les feux de détresse ne servent pas à « se garer en double file deux minutes ».","ref":"Art. 31, 32bis et 39bis AR 01/12/1975"},{"title":"Le klaxon","body":"<p>Le klaxon doit être <b>bref</b> et n'est permis que :</p><ul><li>pour <b>éviter un accident</b> ;</li><li><b>hors agglomération</b>, pour prévenir quelqu'un que tu vas le dépasser.</li></ul><p>En ville, pas de coup de klaxon pour dépasser un cycliste. Et jamais pour saluer un ami.</p><p><b>La nuit</b> (sauf danger imminent), remplace le klaxon par des <b>appels de phares</b> courts (feux de route / feux de croisement en alternance).</p>","tip":"Klaxon = accident à éviter, ou dépassement hors agglo de jour. C'est tout.","ref":"Art. 33 AR 01/12/1975"},{"title":"Ceinture et transport des enfants","body":"<ul><li><b>Tout le monde</b> s'attache, devant comme derrière, même pour 2 km.</li><li>Enfant de <b>moins de 135 cm</b> (et moins de 18 ans) : <b>siège ou rehausseur adapté</b> à sa taille et son poids. C'est la <b>taille</b> qui compte, pas l'âge : à 1,45 m, ton frère de 12 ans peut s'asseoir devant avec la ceinture normale.</li><li><b>Siège bébé dos à la route</b> à l'avant : seulement si l'<b>airbag frontal est désactivé</b>. Sinon, l'airbag frappe le siège.</li><li>Pas plus d'occupants que de <b>places avec ceinture</b> : 5 ceintures = 5 personnes maximum.</li><li>Seule dispense utile pour toi : pendant une <b>marche arrière</b>, le conducteur peut détacher sa ceinture.</li></ul>","tip":"Retiens « 135 cm » : en dessous, rehausseur ; au-dessus, ceinture normale.","ref":"Art. 35 et 44.1 AR 01/12/1975"},{"title":"GSM, fatigue et bonnes habitudes","body":"<ul><li>En roulant, interdit de <b>tenir en main ou manipuler</b> un appareil à écran (GSM, tablette…), même au pas dans un bouchon. Seule exception : l'appareil est <b>fixé dans un support</b> prévu pour ça (GPS par exemple).</li><li>Tu quittes ta voiture, même quelques minutes ? <b>Moteur coupé</b>, frein serré, <b>antivol</b> enclenché.</li><li>Ne laisse pas tourner le moteur à l'arrêt sans nécessité (en attendant devant l'école, par exemple).</li><li>Pluie forte : <b>réduis ta vitesse</b> et <b>augmente ta distance</b>. La limite affichée est un maximum, pas un objectif.</li></ul><p><b>Fatigue et médicaments</b> : tu dois toujours être <b>en état de conduire</b> et garder le <b>contrôle</b> de ta voiture.</p><ul><li>Tu bâilles, tes paupières sont lourdes ? <b>Arrête-toi</b> dans un endroit sûr (aire de repos) et repose-toi. Fenêtre ouverte et musique ne font gagner que quelques minutes.</li><li>Médicament qui donne de la <b>somnolence</b> (lis la notice) : ne conduis que si tu es vraiment en état. Conduire « comme ivre » à cause de médicaments est puni comme l'ivresse.</li></ul>","tip":"GSM : à l'arrêt ou dans un support (rouler au pas, ce n'est pas être à l'arrêt). Contre la fatigue, un seul remède : le repos.","ref":"Art. 8.3, 8.4, 8.5, 8.6 et 10.1 AR 01/12/1975 ; art. 35 Loi du 16/03/1968"},{"title":"Chargement et remorque","body":"<ul><li>Le chargement ne doit masquer <b>ni les feux, ni la plaque</b>, ni gêner ta vue. Un porte-vélos qui cache la plaque : interdit.</li><li><b>À l'avant</b> : le chargement ne dépasse <b>jamais</b>.</li><li><b>À l'arrière</b> (voiture) : <b>1 m maximum</b> en général.</li><li>Dépassement de <b>plus de 1 m</b> à l'arrière : <b>panneau carré de 0,50 m</b> à bandes rouges et blanches. La nuit, ajoute un <b>feu rouge</b> vers l'arrière et des <b>catadioptres orange</b> sur les côtés.</li></ul><p><b>Remorque avec le permis B</b> : toujours permis si la remorque fait <b>750 kg</b> MMA maximum. Plus lourde : permis si l'<b>ensemble</b> voiture + remorque ne dépasse pas <b>3.500 kg</b> MMA (4.250 kg avec le code 96).</p>","tip":"Voiture 2.000 kg + remorque 1.000 kg = 3.000 kg : OK avec un permis B simple.","ref":"Art. 45, 46.2 et 47 AR 01/12/1975 ; AR 23/03/1998"},{"title":"Panne, triangle et accident","body":"<p><b>À bord obligatoirement</b> : triangle de danger, extincteur et trousse de secours. Pneus : rainures d'au moins <b>1,6 mm</b>.</p><p><b>En panne</b> : range ta voiture comme pour un stationnement. Si c'est possible à un endroit autorisé, pas besoin de triangle. Si elle reste là où l'arrêt est interdit, place le <b>triangle</b> à au moins <b>30 m</b> derrière (<b>100 m</b> sur autoroute), visible à environ <b>50 m</b>. Sur autoroute et route pour automobiles : <b>veste fluo</b> dès que tu sors.</p><p><b>Accident sans blessé</b> : reste sur place, faites le <b>constat</b> ensemble (sinon, la police). Voiture abîmée sans son propriétaire ? Laisse ton <b>nom et adresse</b>, ou passe par la police au plus tôt.</p><p><b>Accident avec blessé</b> : sécurise, <b>porte secours</b>, reste sur place pour la police. Tu n'es pas obligé de déplacer ta voiture. Si aucun policier n'a pu venir, déclare l'accident dans les <b>24 heures</b>.</p>","tip":"Triangle : 30 m ailleurs, 100 m sur autoroute. Blessé : déclaration au plus tard 24 h.","ref":"Art. 51, 52 et 81 AR 01/12/1975"},{"title":"Alcool et drogues","body":"<ul><li>Conducteur ordinaire : infraction dès <b>0,5 g/l de sang</b> = <b>0,22 mg/l d'air expiré</b>.</li><li>Dès 0,22 mg/l (ou si tu refuses le test) : <b>interdiction de conduire 12 heures</b> et permis remis à la police.</li><li>Amende : 200 à 4.000 € entre 0,22 et 0,35 mg/l ; <b>1.600 à 16.000 €</b> dès <b>0,35 mg/l</b> (0,8 g/l).</li><li>Chauffeurs de camion (C) et bus (D) : limite à <b>0,2 g/l</b> (0,09 mg/l).</li><li>Le <b>guide</b> qui t'accompagne est soumis aux <b>mêmes limites</b> que s'il conduisait.</li><li>Prêter tes clés à un ami visiblement ivre : <b>c'est toi aussi</b> qui commets une infraction.</li><li><b>Drogues</b> (cannabis, cocaïne, amphétamines…) : test salivaire positif = <b>12 heures</b> d'interdiction, même si tu te sens bien.</li></ul>","tip":"0,5 g/l de sang = 0,22 mg/l d'haleine. Le plus sûr : 0 verre si tu conduis.","ref":"Art. 34, 37, 37bis, 60, 61 et 61ter Loi du 16/03/1968"},{"title":"Permis provisoire et guide","body":"<ul><li>Tu peux conduire avec un permis provisoire B dès <b>17 ans</b>.</li><li>Le <b>guide</b> : titulaire du permis B depuis au moins <b>8 ans</b>, pas de déchéance du droit de conduire ces <b>3 dernières années</b>, et <b>inscrit sur ton permis provisoire</b>.</li><li>À bord : uniquement ton ou tes <b>guides</b> et/ou un <b>instructeur</b>. Pas d'autre passager, même ton petit frère.</li><li><b>Pas de conduite de 22 h à 6 h</b> les nuits du vendredi, samedi, dimanche, la veille des jours fériés et les jours fériés.</li><li>Signe <b>« L » à l'arrière</b>, bien visible, et ton permis provisoire valide sur toi.</li></ul>","tip":"8 ans de permis pour le guide ; 22 h – 6 h le week-end : interdit.","ref":"Art. 3 et 6 AR 10/07/2006 ; art. 8.2 AR 01/12/1975"}],"keypoints":["Feux : allumer si visibilité < 200 m ; croisement si tu suis à < 50 m.","Brouillard arrière : seulement si visibilité < 100 m ou forte pluie.","Klaxon : pour éviter un accident ou dépasser hors agglo ; la nuit, appels de phares.","Enfant < 135 cm : siège adapté ; pas de siège dos à la route devant un airbag actif.","GSM en main interdit en roulant, même au pas.","Triangle : 30 m (100 m sur autoroute) ; accident avec blessé : déclaration dans les 24 h.","Alcool : 0,5 g/l = 0,22 mg/l → 12 h d'interdiction ; même règle pour le guide.","Permis provisoire : guide 8 ans de permis, pas de passager, pas de 22 h–6 h le week-end, « L » à l'arrière."]},"signalisation":{"theme":"signalisation","title":"Panneaux, feux et marquages","intro":"À l'examen, beaucoup de questions te montrent un panneau ou un feu et te demandent quoi faire. La bonne nouvelle : la forme et la couleur d'un panneau te disent déjà sa famille avant même de lire le symbole. Apprends la logique, et tu reconnaîtras même les panneaux que tu n'as jamais vus.","sections":[{"title":"Qui commande ? La hiérarchie des signaux","body":"<p>Quand plusieurs indications se contredisent, retiens cet ordre :</p><ol><li>les <b>injonctions des agents qualifiés</b> (police…) ;</li><li>la <b>signalisation</b> : feux, panneaux, marquages ;</li><li>les <b>règles de circulation</b> (par exemple la priorité de droite).</li></ol><p>Exemples :</p><ul><li>Feu vert, mais l'agent lève le bras verticalement ? Tu <b>t'arrêtes</b> (sauf si tu es déjà dans le carrefour : tu l'évacues).</li><li>Tu roules sur une route avec un <b>B9</b> (voie prioritaire) ? Le panneau l'emporte sur la priorité de droite : tu as la priorité.</li><li>Quand les <b>feux fonctionnent</b>, les panneaux de priorité placés sur la même voie sont sans effet. Exception : le <b>feu orange clignotant</b>, qui laisse les panneaux s'appliquer.</li></ul><p>La signalisation routière se divise en trois catégories : <b>feux</b>, <b>panneaux</b> et <b>marques au sol</b>. Les panneaux, eux, forment six familles (A à F), détaillées ci-dessous.</p>","signs":["B9"],"tip":"Agent, puis panneaux et feux, puis règles : celui qui est « vivant » commande toujours.","ref":"Art. 4.2, 6 et 60.1 AR 01/12/1975"},{"title":"Les feux de signalisation","body":"<p>Ordre des feux : <b>vert → orange → rouge → vert</b>. Il n'y a pas d'orange entre le rouge et le vert.</p><ul><li><b>Rouge</b> : interdiction de franchir la ligne d'arrêt ou, s'il n'y en a pas, le feu lui-même.</li><li><b>Orange fixe</b> : même interdiction. Seule exception : tu es si près au moment où il s'allume que tu ne peux plus t'arrêter en sécurité. Tu passes alors la ligne, mais tu ne traverses le carrefour que sans mettre les autres en danger. À 60 m, tu as le temps : tu t'arrêtes.</li><li><b>Vert</b> : tu peux passer (mais pas si tu vas rester bloqué au milieu du carrefour).</li><li><b>Orange clignotant</b> : tu peux passer en <b>redoublant de prudence</b>. Il ne change pas les priorités : panneaux ou, à défaut, priorité de droite.</li><li><b>Flèche verte avec le feu rouge</b> : tu peux aller seulement dans la direction de la flèche, en cédant le passage aux conducteurs venant d'autres directions et aux piétons.</li><li><b>Flèche verte vers la gauche seule, à la sortie du carrefour</b> (flèche d'évacuation) : la circulation d'en face est arrêtée par un feu rouge, tu peux terminer ton virage à gauche.</li></ul><p>Le panneau <b>A33</b> annonce des feux plus loin.</p>","signs":["FEU-rouge","FEU-orange","FEU-vert","FEU-orange-cligno","A33"],"tip":"Orange fixe = « stop si possible », pas « accélère ». Orange clignotant = feux hors service : regarde les panneaux.","ref":"Art. 61, 62 et 64.1 AR 01/12/1975"},{"title":"A – Signaux de danger","body":"<p><b>Forme</b> : triangle pointe en haut, <b>bord rouge</b>, fond blanc, symbole noir. Ils t'<b>avertissent</b> d'un danger plus loin : ralentis et prépare-toi.</p><ul><li><b>A1a</b> : virage dangereux à gauche ; <b>A1b</b> : à droite.</li><li><b>A7a</b> : rétrécissement de la chaussée.</li><li><b>A33</b> : feux de signalisation.</li><li><b>A51</b> (point d'exclamation) : danger sans symbole spécial ; un panneau additionnel en dessous en précise la nature.</li></ul>","signs":["A1a","A1b","A7a","A33","A51"],"tip":"Pour A1a/A1b, regarde où part le haut de la flèche : c'est le sens du premier virage.","ref":"Art. 66 AR 01/12/1975"},{"title":"B – Signaux de priorité","body":"<p>Ce sont les seuls panneaux aux formes « spéciales », pour être reconnus même de dos ou sous la neige :</p><ul><li><b>B1</b> : triangle <b>pointe en bas</b> – cédez le passage (arrêt seulement si nécessaire).</li><li><b>B5</b> : <b>octogone rouge</b> STOP – arrêt obligatoire, même si personne n'arrive, puis céder le passage.</li><li><b>B9</b> : <b>losange jaune</b> bordé de blanc – voie prioritaire. <b>B11</b> : le même barré – fin de voie prioritaire (la priorité de droite revient).</li><li><b>B15</b> : triangle avec une flèche épaisse – priorité au <b>prochain</b> carrefour.</li><li><b>B17</b> : triangle avec une croix – carrefour à priorité de droite.</li><li><b>B19</b> (rond, bord rouge) : passage étroit, tu cèdes à ceux d'en face. <b>B21</b> (carré bleu) : passage étroit, tu as la priorité.</li></ul>","signs":["B1","B5","B9","B11","B15","B17","B19","B21"],"tip":"B1 et B5 sont les deux panneaux à distinguer à coup sûr : B1 = on peut « glisser » si c'est libre, B5 = arrêt complet toujours.","ref":"Art. 67.3 AR 01/12/1975"},{"title":"C – Signaux d'interdiction","body":"<p><b>Forme</b> : <b>rond à bord rouge</b> (fond blanc). Ils <b>interdisent</b> quelque chose.</p><ul><li><b>C1</b> (disque rouge, barre blanche) : <b>sens interdit</b>. Un panneau additionnel peut excepter les cyclistes.</li><li><b>C3</b> (rond blanc bordé de rouge, vide) : accès interdit <b>dans les deux sens</b> à tout conducteur.</li><li><b>C31a / C31b</b> : interdit de tourner à gauche / à droite au <b>prochain carrefour</b>.</li><li><b>C33</b> : demi-tour interdit jusqu'au prochain carrefour <b>inclus</b>.</li><li><b>C35</b> : interdit de dépasser par la gauche un véhicule à <b>plus de deux roues</b> ou attelé, jusqu'au prochain carrefour inclus. Une voiture : interdit. Une moto sans side-car : permis (si le reste des règles le permet).</li><li><b>C43</b> : vitesse maximale (30, 50, 70, 90, 120…). <b>C45</b> : fin de cette limitation (même chiffre).</li><li><b>C46</b> : fin de <b>toutes</b> les interdictions locales pour véhicules en mouvement (dépassement, vitesse…). Il ne concerne pas le stationnement.</li></ul><p>Un panneau d'interdiction peut être annoncé à l'avance par le même panneau avec un additionnel « 200 m » : l'interdiction commence à environ 200 m.</p>","signs":["C1","C3","C31a","C31b","C33","C35","C43-50","C45-50","C46"],"tip":"Rond + bord rouge = interdit. Rond + bord rouge + barres noires/grises = fin d'interdiction.","ref":"Art. 68.2, 68.3 et 68.4 AR 01/12/1975"},{"title":"D – Obligation et E – Arrêt et stationnement","body":"<p><b>D – Obligation</b> : <b>rond à fond bleu</b>, symbole blanc. Ils <b>imposent</b> quelque chose.</p><ul><li><b>D1</b> : suivre la direction de la flèche. Placé sur un <b>îlot</b> ou un obstacle, la flèche oblique t'indique de quel côté passer.</li><li><b>D5</b> : sens giratoire obligatoire (rond-point).</li></ul><p><b>E – Arrêt et stationnement</b> : rond à fond bleu et <b>bord rouge</b>, ou carré bleu.</p><ul><li><b>E1</b> (une barre rouge) : stationnement interdit. L'arrêt (déposer quelqu'un) reste permis.</li><li><b>E3</b> (deux barres en croix) : <b>arrêt ET stationnement</b> interdits. Même pas pour laisser descendre un passager.</li><li><b>E9a</b> (carré bleu « P ») : stationnement autorisé.</li></ul>","signs":["D1-up","D1-downright","D5","E1","E3","E9a"],"tip":"Bleu = obligatoire ou autorisé ; rouge = interdit. Une barre (E1) = pas de stationnement ; une croix (E3) = pas même l'arrêt.","ref":"Art. 69.3 et 70.2.1 AR 01/12/1975"},{"title":"F – Signaux d'indication et panneaux additionnels","body":"<p><b>Forme</b> : <b>rectangle ou carré</b>, souvent bleu. Ils t'<b>informent</b> ; les règles liées s'appliquent dès l'endroit du panneau.</p><ul><li><b>F1a</b> : début d'<b>agglomération</b>. <b>F3a</b> (nom barré) : fin d'agglomération. En agglomération : <b>50 km/h</b> en Wallonie et en Flandre, <b>30 km/h</b> à Bruxelles. Hors agglomération : <b>90 km/h</b> en Wallonie, <b>70 km/h</b> en Flandre (sauf panneau).</li><li><b>F4a</b> / <b>F4b</b> : début / fin de <b>zone 30</b>.</li><li><b>F5</b> / <b>F7</b> : début / fin d'<b>autoroute</b>.</li><li><b>F9</b> : <b>route pour automobiles</b> (sa fin : F11).</li><li><b>F19</b> : voie à <b>sens unique</b> (un additionnel peut indiquer que les cyclistes roulent dans les deux sens).</li><li><b>F45</b> : voie <b>sans issue</b> (F45b : sans issue sauf pour piétons et cyclistes).</li></ul><p><b>Panneau additionnel</b> : le petit rectangle sous un panneau (blanc sur bleu, ou noir sur blanc pour les vélos) <b>complète, précise ou limite</b> le signal : horaire, distance, catégorie de véhicules…</p>","signs":["F1a","F3a","F4a","F4b","F5","F7","F9","F19","F45"],"tip":"Ne confonds pas F19 (carré bleu, sens unique : tu peux entrer) et C1 (rond rouge, sens interdit : tu ne peux pas entrer).","ref":"Art. 11, 65.2 et 71 AR 01/12/1975"},{"title":"Les lignes sur la chaussée","body":"<ul><li><b>Ligne blanche continue</b> : personne ne la franchit. Si elle sépare les deux sens, tu ne roules pas à sa gauche. Même pour dépasser un tracteur lent : interdit.</li><li><b>Ligne discontinue</b> : tu la franchis seulement pour <b>dépasser, tourner à gauche, faire demi-tour ou changer de bande</b>. Rouler à cheval dessus : interdit.</li><li><b>Traits plus courts et plus rapprochés</b> : une ligne continue arrive. Ne commence plus de dépassement.</li><li><b>Continue + discontinue côte à côte</b> : tu suis seulement celle de <b>ton côté</b>. Si tu les as franchies pour dépasser, tu peux revenir à ta place.</li><li><b>Lignes orange</b> (travaux) : elles <b>annulent</b> les lignes blanches au même endroit et ont la même signification.</li><li><b>Ligne jaune discontinue</b> le long du bord : stationnement interdit à cet endroit.</li></ul>","tip":"Ligne continue = mur. Ligne discontinue = porte qu'on ouvre seulement pour une raison précise.","ref":"Art. 72, 73 et 75.1 AR 01/12/1975"},{"title":"Marques transversales et autres marquages","body":"<ul><li><b>Ligne d'arrêt</b> (ligne blanche continue en travers) : là où tu t'arrêtes au <b>stop</b> ou au <b>feu</b>.</li><li><b>Ligne de triangles blancs</b> : là où tu t'arrêtes, si besoin, pour céder le passage (<b>B1</b>).</li><li><b>Passage pour piétons</b> : bandes blanches parallèles à l'axe de la route.</li><li><b>Flèches de sélection</b> : à l'approche d'un carrefour, tu dois suivre la direction indiquée sur <b>ta</b> bande. Flèche à droite = tu tournes à droite.</li><li><b>Flèches de rabattement</b> (obliques, le long d'une ligne discontinue) : le nombre de bandes diminue, rabats-toi.</li><li><b>Hachures obliques</b> (îlot, zone d'évitement) : ni circuler, ni s'arrêter, ni stationner.</li><li><b>Damier blanc</b> (site de bus/tram, passage à niveau) : arrêt et stationnement interdits.</li><li><b>Zone avancée vélo</b> (entre deux lignes d'arrêt avec un vélo dessiné) : en voiture, tu t'arrêtes devant la <b>première</b> ligne d'arrêt.</li></ul>","tip":"Au feu rouge avec zone vélo : la première ligne est pour toi, l'espace devant est pour les cyclistes.","ref":"Art. 76 et 77 AR 01/12/1975"}],"keypoints":["Ordre de force : agent, puis feux et panneaux, puis règles de circulation.","Triangle bord rouge = danger ; rond bord rouge = interdiction ; rond bleu = obligation ; rectangle = indication.","B5 octogone : arrêt toujours. B1 triangle pointe en bas : céder, arrêt si nécessaire. B9 losange jaune : prioritaire.","Feux : vert, orange, rouge. Orange fixe = arrêt sauf si trop près. Orange clignotant = prudence, priorités inchangées.","E1 = stationnement interdit ; E3 = arrêt et stationnement interdits.","Agglomération : 50 km/h (Wallonie, Flandre), 30 km/h à Bruxelles. Hors agglo : 90 (Wallonie), 70 (Flandre).","Ligne continue : jamais franchie. Lignes juxtaposées : seule celle de ton côté compte. Lignes orange > lignes blanches.","Hachures et damier : ni arrêt ni stationnement."]},"stationnement":{"theme":"stationnement","title":"S'arrêter et stationner","intro":"Se garer, tout le monde pense savoir le faire… jusqu'à la question sur les 5 m, 15 m ou 20 m ! Ce thème est rempli de chiffres faciles à retenir : apprends-les une fois et tu prends des points faciles à l'examen.","sections":[{"title":"Arrêt ou stationnement ?","body":"<p>Tout part de cette différence :</p><ul><li><b>À l'arrêt</b> : ta voiture est immobilisée <b>juste le temps</b> de faire monter ou descendre quelqu'un, ou de charger ou décharger des choses.</li><li><b>En stationnement</b> : dès que tu restes <b>plus longtemps</b> que ça. Tu déposes un ami et tu repars : arrêt. Tu vas acheter ton pain : stationnement.</li><li>Faire le <b>plein</b> ou <b>recharger</b> une voiture électrique = <b>stationnement</b>.</li></ul>","tip":"Le chauffeur quitte la voiture pour une course ? C'est du stationnement, même pour 2 minutes.","ref":"Art. 2.22 et 2.23 AR 01/12/1975"},{"title":"Où et comment te ranger","body":"<ul><li>En principe <b>à droite</b> par rapport à ton sens de marche. Sur une chaussée <b>à sens unique</b> : à droite <b>ou</b> à gauche.</li><li>D'abord <b>hors de la chaussée</b>, sur l'accotement de plain-pied (hors agglomération, sur tout accotement). Laisse aux piétons une bande d'au moins <b>1,50 m</b> côté extérieur.</li><li>Accotement trop étroit : en partie sur l'accotement, en partie sur la chaussée. Pas d'accotement praticable : sur la chaussée.</li><li>Sur la chaussée : <b>le plus loin possible de l'axe</b>, <b>parallèlement au bord</b> (sauf aménagement) et <b>en une seule file</b>.</li><li>Laisse <b>1 m</b> devant et derrière les autres véhicules, et au moins <b>3 m</b> de passage libre sur la chaussée.</li></ul>","signs":["F19"],"tip":"1,50 m pour les piétons, 1 m entre deux voitures, 3 m pour la circulation.","ref":"Art. 23 et 25.1 AR 01/12/1975"},{"title":"Arrêt ET stationnement interdits","body":"<p>Ici, tu ne peux <b>même pas t'arrêter</b> quelques secondes :</p><ul><li>sur les <b>trottoirs</b> et, en agglomération, les accotements en saillie (sauf réglementation locale) ;</li><li>sur les <b>pistes cyclables</b> et à moins de 5 m de l'endroit où les cyclistes y entrent ou en sortent ;</li><li>sur les <b>passages à niveau</b> ;</li><li>sur les passages pour piétons et pour cyclistes, et à moins de <b>5 m avant</b> ceux-ci ;</li><li>dans les <b>tunnels</b>, passages inférieurs et sous les ponts (sauf réglementation locale) ;</li><li>près du <b>sommet d'une côte</b> ou dans un <b>virage</b> sans visibilité suffisante ;</li><li>à moins de <b>5 m d'un carrefour</b> (mesurés depuis le prolongement du bord de la chaussée transversale) ;</li><li>à moins de <b>20 m avant un feu</b> ou un <b>panneau routier</b> ;</li><li>sur les <b>dispositifs surélevés</b> (casse-vitesse) et sur les <b>marques obliques blanches</b> (zones d'évitement).</li></ul><p>Exception pour les 20 m avant un panneau ou un feu hors carrefour : elle ne s'applique pas si ton véhicule fait <b>1,65 m de haut maximum</b> et que le bas du signal est à <b>2 m au moins</b> du sol.</p>","signs":["FEU-rouge"],"tip":"5 m : passage piétons, carrefour, piste cyclable. 20 m : feux et panneaux (pour ne pas les cacher).","ref":"Art. 24 et 77.4 AR 01/12/1975"},{"title":"Stationnement interdit (l'arrêt reste permis)","body":"<ul><li>À moins de <b>15 m de part et d'autre</b> d'un panneau d'arrêt de bus, trolleybus ou tram.</li><li>Devant une <b>entrée de garage</b>, sauf pour le véhicule dont la <b>plaque</b> est reproduite lisiblement sur l'accès.</li><li>Le long d'une <b>ligne jaune discontinue</b> au bord de la chaussée ou du trottoir.</li><li><b>Hors agglomération</b> sur la chaussée d'une <b>route prioritaire</b> (signal B9).</li><li>Sur une chaussée <b>divisée en bandes de circulation</b>, sauf là où un signal E9a (ou E9b) l'autorise.</li><li>Là où les piétons ou cyclistes doivent contourner un obstacle par la chaussée, ou si tu bloques un autre véhicule.</li><li>Sur un emplacement <b>réservé aux personnes handicapées</b>, si tu n'as pas la <b>carte spéciale</b> derrière le pare-brise, même pour 5 minutes.</li></ul>","signs":["B9","E9a"],"tip":"Ligne jaune discontinue = pas de stationnement, mais tu peux t'arrêter pour déposer quelqu'un.","ref":"Art. 25.1, 27bis et 75.1.2° AR 01/12/1975"},{"title":"Les panneaux E1, E3 et E9a","body":"<ul><li><b>E1</b> (rond bleu barré d'un trait) : <b>stationnement interdit</b>. L'arrêt pour charger ou décharger reste permis.</li><li><b>E3</b> (rond bleu barré d'une croix) : <b>arrêt et stationnement interdits</b>.</li><li><b>E9a</b> (« P » blanc sur fond bleu) : stationnement <b>autorisé</b>.</li><li>Ces signaux valent <b>du côté où ils sont placés</b>, depuis le panneau <b>jusqu'au prochain carrefour</b>. Une inscription peut limiter les jours ou les heures.</li></ul>","signs":["E1","E3","E9a"],"tip":"Un trait = une interdiction (stationner). Une croix = deux interdictions (s'arrêter et stationner).","ref":"Art. 70.2.1 et 70.2.2 AR 01/12/1975"},{"title":"Zone bleue et stationnement payant","body":"<p>En <b>zone bleue</b>, tu places ton <b>disque de stationnement</b> derrière le pare-brise.</p><ul><li>Sauf indication contraire : obligatoire <b>les jours ouvrables de 9 h à 18 h</b>, pour <b>2 heures maximum</b>.</li><li>La flèche se met sur le <b>trait qui suit</b> ton heure d'arrivée (traits par demi-heure). Arrivé à 10 h 05 ? Flèche sur <b>10 h 30</b>.</li><li>Interdit de tricher sur le disque ou de le modifier sans avoir quitté la place.</li><li><b>Parcmètre ou horodateur en panne</b> : tu utilises ton disque.</li><li>La carte communale (riverain…) ou la carte pour personnes handicapées remplace le disque.</li></ul>","tip":"Toujours arrondir vers le trait SUIVANT : tu gagnes au maximum une demi-heure.","ref":"Art. 27.1, 27.3 et 27.4 AR 01/12/1975"},{"title":"Stationnement alterné semi-mensuel","body":"<p>Certaines communes l'imposent dans toute l'agglomération (panneau à l'entrée).</p><ul><li>Du <b>1er au 15</b> du mois : côté des numéros <b>impairs</b>.</li><li>Du <b>16 à la fin</b> du mois : côté des numéros <b>pairs</b>.</li><li>Tu changes de côté <b>le dernier jour de la période, entre 19 h 30 et 20 h</b>.</li></ul>","tip":"Début du mois = impair (1 est impair). Fin du mois = pair.","ref":"Art. 26 et 70.2.1.2° AR 01/12/1975"},{"title":"Ouvrir ta portière en sécurité","body":"<p>Tu es garé le long du trottoir et tu veux sortir côté chaussée. Avant d'ouvrir, <b>regarde dans le rétroviseur et par-dessus ton épaule</b> : un cycliste ou un scooter arrive peut-être.</p><ul><li>Interdit d'ouvrir une portière, de la laisser ouverte, de monter ou de descendre <b>sans t'être assuré</b> que cela ne crée ni danger ni gêne, surtout pour les <b>piétons</b> et les <b>deux-roues</b>.</li></ul>","tip":"Astuce : ouvre la portière avec la main la plus éloignée (main droite pour le conducteur). Ton corps pivote et tu regardes naturellement derrière toi.","ref":"Art. 28 AR 01/12/1975"}],"keypoints":["Arrêt = juste le temps de charger ou décharger ; au-delà, plein ou recharge compris = stationnement.","Se ranger à droite (des deux côtés si sens unique), parallèlement, en une seule file.","5 m : passage piétons, carrefour. 20 m : feux et panneaux.","15 m de part et d'autre d'un arrêt de bus ; 1 m entre véhicules ; 3 m de passage libre ; 1,50 m pour les piétons.","E1 = stationnement interdit ; E3 = arrêt et stationnement interdits ; effet jusqu'au prochain carrefour.","Zone bleue : 9 h-18 h, jours ouvrables, 2 h max, flèche sur le trait suivant.","Alterné : impairs du 1 au 15, pairs du 16 à la fin ; changement entre 19 h 30 et 20 h.","Place PMR : uniquement avec la carte spéciale ; portière : regarder avant d'ouvrir."]},"usagers":{"theme":"usagers","title":"Piétons, cyclistes et autres usagers","intro":"Les piétons, cyclistes et enfants ne sont pas protégés par une carrosserie : une erreur envers eux est presque toujours une faute grave à l'examen. Retiens qui doit céder le passage, les distances latérales et les règles des zones spéciales, et tu as déjà la plupart des points de ce thème.","sections":[{"title":"Les piétons : quand dois-tu leur céder le passage ?","body":"<p>Tu arrives à un <b>passage pour piétons sans feux ni agent</b> : tu t'en approches à <b>allure modérée</b> et tu cèdes le passage aux piétons <b>déjà engagés</b> ou <b>sur le point de s'engager</b> (celui qui attend au bord, prêt à traverser).</p><ul><li><b>Avec des feux ou un agent</b> : même si ton feu passe au vert, tu laisses le piéton régulièrement engagé <b>finir sa traversée</b> à allure normale.</li><li>Au <b>feu rouge</b>, tu t'arrêtes <b>avant</b> le passage pour piétons, jamais dessus.</li><li><b>Bouchon</b> : tu ne t'engages pas sur le passage si tu risques d'y rester immobilisé.</li><li><b>Tu tournes</b> (à droite ou à gauche) : tu cèdes le passage aux piétons qui traversent la rue où tu entres, <b>même avec un feu vert</b> et <b>même sans passage pour piétons</b>.</li></ul>","signs":["FEU-vert","FEU-rouge"],"tip":"Piège classique : « mon feu est vert, donc je passe ». Faux ! Quand tu tournes, le piéton qui traverse la rue où tu t'engages passe toujours avant toi.","ref":"Art. 19.5, 40.4 et 40.5 AR 01/12/1975"},{"title":"Piétons sur la chaussée et personnes vulnérables","body":"<p>Pas de trottoir ? Le piéton marche sur la chaussée, <b>le plus près du bord</b>, en principe <b>à gauche</b> (face à toi), ou à droite si c'est plus sûr.</p><ul><li>Distance latérale minimale : <b>1 m en agglomération</b>, <b>1,5 m hors agglomération</b>. Impossible ? Tu roules à <b>l'allure du pas</b> et tu t'arrêtes au besoin.</li><li>Obstacle sur le trottoir (voiture mal garée, travaux) que les piétons contournent par la chaussée : laisse <b>1 m</b> le long de l'obstacle ; sinon, si un piéton est à sa hauteur, passe <b>au pas</b>.</li><li><b>Enfants, personnes âgées, personnes handicapées</b>, aveugle avec une <b>canne blanche ou jaune</b>, voiturette : tu <b>redoubles de prudence</b>, tu ralentis et au besoin tu t'arrêtes.</li></ul>","tip":"Canne blanche = « je ne te vois pas ». C'est toi qui t'adaptes : ralentis et prépare-toi à t'arrêter.","ref":"Art. 40.2, 40.6, 40.7 et 42.1 AR 01/12/1975"},{"title":"Cyclistes, speed pedelecs et trottinettes","body":"<p>Tu dépasses un cycliste ? Laisse au moins <b>1 m en agglomération</b> et <b>1,5 m hors agglomération</b>. Les <b>trottinettes électriques</b> (engins de déplacement motorisés) sont <b>assimilées aux cyclistes</b> : mêmes règles envers elles.</p><ul><li>Les cyclistes peuvent rouler <b>à deux de front</b>, sauf si le croisement est impossible. <b>Hors agglomération</b>, ils se mettent en file quand un véhicule arrive derrière eux.</li><li>Un enfant de <b>moins de 10 ans</b> à vélo peut rouler sur le <b>trottoir</b>.</li><li><b>Speed pedelec</b> (vélo électrique rapide) : là où la vitesse autorisée dépasse <b>50 km/h</b>, il <b>doit</b> prendre la piste cyclable (D7 ou marquée) si elle existe et est praticable ; à <b>50 km/h ou moins</b>, il <b>peut</b> la prendre.</li><li>Sens unique avec panneau additionnel « vélo » (M4) : les cyclistes roulent <b>dans les deux sens</b> ; attends-toi à en croiser.</li><li>Panneau <b>B22</b> au feu : le cycliste peut tourner à droite au rouge ou à l'orange, en cédant le passage.</li></ul>","signs":["F19"],"tip":"1 et 1,5 : le même chiffre vaut pour les piétons et les cyclistes. En agglo 1 m, hors agglo 1,5 m.","ref":"Art. 7bis, 9.1.2, 40ter, 43.2 et 71.3 AR 01/12/1975"},{"title":"Pistes cyclables : céder le passage","body":"<p>Tu tournes à droite et un cycliste arrive <b>derrière toi</b> sur la piste cyclable pour continuer tout droit : <b>c'est toi qui cèdes</b>. Qui change de direction cède à ceux qui circulent sur les autres parties de la même voie publique (piste cyclable, trottoir).</p><ul><li>Tu sors de ton garage et tu traverses un <b>trottoir</b> ou une <b>piste cyclable</b> : tu cèdes le passage à ceux qui y circulent.</li><li><b>Zone avancée pour cyclistes</b> (vélo blanc peint entre deux lignes d'arrêt) : au rouge, tu t'arrêtes <b>devant la première ligne</b> ; la zone est pour les vélos et cyclomoteurs à deux roues.</li><li>Approche les <b>passages pour cyclistes</b> à allure modérée et ne t'y engage pas si tu risques d'y rester bloqué.</li></ul>","signs":["FEU-rouge"],"tip":"Avant de tourner à droite : rétroviseur ET coup d'œil dans l'angle mort. Le cycliste à ta droite est prioritaire.","ref":"Art. 12.4bis, 19.4, 40ter et 77.6 AR 01/12/1975"},{"title":"Zones résidentielles, piétonnes, cyclables et chemins réservés","body":"<ul><li><b>Zone résidentielle / de rencontre</b> : les piétons utilisent <b>toute la largeur</b>, les <b>jeux sont autorisés</b>. Vitesse max <b>20 km/h</b>. Tu ne mets personne en danger et tu t'arrêtes au besoin. Stationnement <b>interdit</b>, sauf sur les emplacements marqués d'un <b>« P »</b> ou là où un signal l'autorise.</li><li><b>Zone piétonne</b> : réservée aux piétons. Les véhicules admis (garage dans la zone, livraisons autorisées, secours, bus…) roulent <b>à l'allure du pas</b> et cèdent le passage aux piétons. Pour ton garage, il te faut un <b>laissez-passer du bourgmestre</b> derrière le pare-brise. Stationnement <b>toujours interdit</b>.</li><li><b>Zone cyclable</b> : les voitures peuvent y rouler mais <b>ne peuvent pas dépasser les cyclistes</b> (ni les speed pedelecs). Max <b>30 km/h</b>. Le cycliste peut prendre toute la largeur (sens unique) ou la moitié droite (double sens).</li><li><b>Chemin réservé</b> aux piétons, cyclistes, cavaliers et speed pedelecs : interdit aux voitures, sauf véhicules prioritaires en mission et véhicules autorisés par le gestionnaire (riverains, fournisseurs, entretien, immondices). Max <b>30 km/h</b>.</li></ul>","tip":"Résidentielle = 20 ; cyclable et chemin réservé = 30 ; piétonne = allure du pas.","ref":"Art. 22bis, 22quinquies, 22sexies et 22novies AR 01/12/1975"},{"title":"Abords d'école et groupes d'enfants","body":"<p>Les <b>abords d'école</b> sont délimités par les signaux <b>F4a</b> (début, avec le panneau « enfants » A23) et <b>F4b</b> (fin) : vitesse limitée à <b>30 km/h</b>.</p><ul><li>Un <b>surveillant habilité</b> lève un disque rouge et blanc (signal <b>C3</b>) : tu <b>t'arrêtes</b> et tu obéis à ses indications.</li><li>Il est <b>interdit de couper</b> un groupe d'enfants, d'écoliers, de personnes âgées ou handicapées en rangs avec un guide, ou qui traverse avec un surveillant, même s'il reste un trou entre deux rangs.</li><li><b>Rue scolaire</b> : réservée aux piétons et cyclistes ; les véhicules autorisés y roulent <b>au pas</b>.</li></ul>","signs":["F4a","F4b","C3"],"tip":"Le disque C3 du surveillant a la même valeur qu'un ordre d'agent : on s'arrête, point.","ref":"Art. 2.37, 22quater, 22undecies et 40bis AR 01/12/1975"},{"title":"Bus, trams et transport scolaire","body":"<ul><li>Tu longes un bus, un car ou un tram <b>arrêté pour des voyageurs</b> : tu <b>modères ta vitesse</b>.</li><li>Arrêt <b>sans refuge</b> et tu roules du côté où les voyageurs montent ou descendent : tu <b>t'arrêtes</b> pour les laisser passer, puis tu repars à allure modérée.</li><li><b>En agglomération</b>, un bus met son clignotant pour quitter son arrêt : tu <b>ralentis</b> et au besoin tu t'arrêtes pour le laisser partir. Cette règle ne vaut <b>qu'en agglomération</b>.</li><li><b>Transport scolaire</b> (panneau spécial à l'avant et à l'arrière) : prudence redoublée. S'il allume <b>tous ses clignotants</b>, des enfants montent ou descendent : <b>ralentis fortement</b> et arrête-toi au besoin.</li></ul>","signs":["F1a"],"tip":"Bus qui clignote pour repartir : priorité au bus, mais seulement en agglomération (panneau F1a).","ref":"Art. 39, 39bis et 40.3 AR 01/12/1975"},{"title":"Animaux, cavaliers et courses cyclistes","body":"<ul><li><b>Cavaliers</b> : ils peuvent rouler <b>à deux de front</b> sur la chaussée. Dépasse-les calmement, avec une large marge.</li><li><b>Animaux</b> (troupeau, chevaux attelés) : leur conducteur doit rester près d'eux et les maîtriser ; en agglomération, interdit de les faire galoper. Toi, tu ralentis et tu évites de les effrayer.</li><li><b>Course cycliste</b> : à l'approche du véhicule au <b>drapeau rouge</b>, tu t'écartes, tu dégages la chaussée et tu <b>t'arrêtes</b>. Tu attends le passage du véhicule au <b>drapeau vert</b> pour repartir.</li></ul>","tip":"Drapeau rouge = je m'arrête ; drapeau vert = c'est fini, je peux repartir.","ref":"Art. 40quater et 55 AR 01/12/1975"}],"keypoints":["Passage pour piétons sans feux : céder aux piétons engagés ou sur le point de s'engager.","En tournant, on cède aux piétons qui traversent, même au feu vert.","Distance latérale piéton ou cycliste : 1 m en agglo, 1,5 m hors agglo.","Zone résidentielle 20 km/h ; zone cyclable, chemin réservé et abords d'école 30 km/h ; zone piétonne au pas.","Zone cyclable : interdit de dépasser les cyclistes.","En agglo, laisser repartir le bus qui clignote ; transport scolaire avec tous les clignotants = ralentir fortement.","Surveillant avec disque C3 : s'arrêter ; ne jamais couper un groupe d'enfants.","Course cycliste : arrêt du drapeau rouge au drapeau vert."]},"vitesse":{"theme":"vitesse","title":"La vitesse : limites, zones et distance de sécurité","intro":"La vitesse, c'est le thème où les pièges sont les plus nombreux : les limites changent selon la Région, le type de route et les panneaux. Et rouler trop vite près d'une école ou dans une zone de rencontre peut te coûter une faute grave. Retiens les chiffres clés et surtout une idée : la limite affichée est un maximum, pas un objectif.","sections":[{"title":"La limite n'est pas une obligation : adapte ta vitesse","body":"<p>Tu roules sur une route limitée à 90 km/h, mais il pleut fort et tu vois mal. Rouler à 90 serait légal… sur le papier seulement. Le code t'oblige à <b>régler ta vitesse</b> selon :</p><ul><li>la présence d'autres usagers, <b>surtout les plus vulnérables</b> (enfants, piétons, cyclistes) ;</li><li>la météo, la visibilité, l'état de la route ;</li><li>la disposition des lieux, l'encombrement, la densité du trafic ;</li><li>l'<b>état et le chargement de ton véhicule</b> (coffre plein, galerie de toit…).</li></ul><p>Ta vitesse ne peut jamais être une cause d'accident ni une gêne pour la circulation. Et en toute circonstance, tu dois <b>pouvoir t'arrêter devant un obstacle prévisible</b>. La nuit, en feux de croisement, ça veut dire rouler assez lentement pour t'arrêter dans la zone éclairée.</p>","signs":["C43-90"],"tip":"À l'examen, si la question parle de pluie, de brouillard, d'enfants ou de chargement, la bonne réponse est presque toujours « adapter (réduire) sa vitesse », même si la limite est respectée.","ref":"Art. 10.1 AR 01/12/1975"},{"title":"Ni trop lent, ni freinage brutal","body":"<p>Rouler trop doucement peut aussi être une faute :</p><ul><li>Tu ne peux pas gêner les autres en roulant <b>sans raison valable à une vitesse anormalement réduite</b> (ex. 30 km/h sur une route dégagée à 90).</li><li>Tu ne peux pas <b>freiner brusquement</b> sans raison de sécurité (« donner une leçon » à celui qui te suit est interdit et dangereux).</li><li>Pour ralentir fortement, tu le signales avec tes <b>feux-stop</b> (ou un geste du bras si le véhicule n'en a pas).</li></ul><p>Quelques cas particuliers :</p><ul><li>Tu approches de <b>chevaux, bétail ou animaux de trait</b> : tu ralentis. S'ils montrent des <b>signes de frayeur</b>, tu t'<b>arrêtes</b>.</li><li>Il est interdit d'<b>inciter ou provoquer</b> un conducteur à rouler trop vite : le passager qui te pousse à « tester la voiture » est en infraction.</li><li>Sur autoroute, sauf C43 plus bas, tu ne peux pas rouler <b>sous 70 km/h</b>.</li></ul>","tip":"Animal effrayé = arrêt, pas seulement ralentir. C'est un piège classique.","ref":"Art. 10.2, 10.3, 10.4 et 21.2 AR 01/12/1975"},{"title":"En agglomération : 50 ou 30 selon la Région","body":"<p>L'agglomération commence au panneau F1 (nom de la commune) et se termine au panneau F3. Sans autre panneau, la limite est :</p><ul><li><b>Wallonie et Flandre : 50 km/h</b> ;</li><li><b>Bruxelles-Capitale : 30 km/h</b>.</li></ul><p>Un panneau C43 peut imposer une vitesse plus basse… ou permettre plus haut (ex. 70 sur une grande avenue).</p><p>Si un <b>C43 « 30 » est placé au-dessus du panneau de début d'agglomération</b>, le 30 vaut sur <b>toutes les voiries</b> de l'agglomération.</p>","signs":["F1a","F3a","C43-50","C43-30"],"tip":"Bruxelles = 30 par défaut en ville ; Wallonie et Flandre = 50. Lis bien la Région citée dans la question.","ref":"Art. 11.1 et 68 (C43) AR 01/12/1975"},{"title":"Hors agglomération et sur autoroute","body":"<p>Hors agglomération, sans panneau, pour une voiture :</p><ul><li><b>Autoroute : 120 km/h.</b></li><li><b>Route à 2 × 2 bandes minimum dont les sens sont séparés physiquement</b> (berme centrale, glissière) : <b>120 km/h</b>, comme sur autoroute.</li><li>Route ordinaire, ou 2 × 2 bandes séparées <b>seulement par des lignes au sol</b> :<ul><li><b>Wallonie : 90 km/h</b> (70 sur une chaussée à voie centrale) ;</li><li><b>Flandre : 70 km/h</b>, sauf si un C43 permet 90 ;</li><li><b>Bruxelles : 70 km/h</b>.</li></ul></li></ul><p>Véhicules de <b>plus de 3,5 tonnes</b> (masse maximale autorisée), autobus : <b>90 km/h</b> sur autoroute.</p><p>Une limitation plus basse imposée par un <b>C43 reste valable même sur autoroute</b> : zone de travaux à 70 = 70, pas 120.</p>","signs":["F5","C43-120","C43-90","C43-70"],"tip":"Lignes peintes au milieu = route ordinaire (90 en Wallonie, 70 en Flandre). Berme ou glissière + 2 bandes par sens = 120.","ref":"Art. 11.2 AR 01/12/1975"},{"title":"Jusqu'où vaut un panneau de vitesse ?","body":"<p>Tu passes un C43 « 70 » en ville, puis un carrefour. Que vaut la limite ? Un C43 (non zonal) vaut :</p><ul><li>jusqu'au <b>prochain carrefour inclus</b> ;</li><li>ou jusqu'à un autre C43 ;</li><li>ou jusqu'au début/fin d'agglomération, de zone résidentielle, de zone de rencontre ou de zone piétonne.</li></ul><p>Après le carrefour, la <b>limite générale</b> revient (50 en Wallonie/Flandre, 30 à Bruxelles en agglomération).</p><p>Le <b>C45</b> marque la fin de la limitation du C43 correspondant. Le <b>C46</b> annonce la fin de toutes les interdictions locales imposées aux véhicules en mouvement. Ensuite, ce sont les règles générales qui s'appliquent.</p>","signs":["C43-70","C45-50","C46"],"tip":"C43 = « jusqu'au prochain carrefour ». Zone (F4a, zone de rencontre…) = « jusqu'au panneau de fin de zone », même après les carrefours.","ref":"Art. 68 (C43, C45, C46) et 71 (F1) AR 01/12/1975"},{"title":"Zones 30, abords d'école et ralentisseurs","body":"<p>Le panneau <b>F4a</b> marque le début d'une <b>zone 30</b>. La limite vaut <b>jusqu'au F4b</b> (fin de zone), même après plusieurs carrefours.</p><p><b>Abords d'école</b> : zone autour d'un accès d'école, délimitée par <b>F4a et F4b</b>, avec le signal A23 (enfants) associé au F4a. Donc : <b>30 km/h maximum</b>. Et même à 30, à l'heure de sortie des classes, tu ralentis encore si nécessaire.</p><p><b>Dispositif surélevé</b> (ralentisseur, plateau) annoncé par la signalisation : tu l'approches prudemment et tu le franchis à <b>30 km/h maximum</b>. Il est aussi <b>interdit d'y dépasser</b>.</p>","signs":["F4a","F4b"],"tip":"École = 30, ralentisseur = 30 max. Excès près d'une école : les enfants sont imprévisibles, l'examinateur ne pardonne pas.","ref":"Art. 2.37, 22ter, 22quater et 17.2.7° AR 01/12/1975"},{"title":"Zones résidentielles et zones de rencontre : 20 km/h","body":"<p>Dans une <b>zone résidentielle</b> ou une <b>zone de rencontre</b> (panneau F12a) :</p><ul><li>la vitesse est limitée à <b>20 km/h</b> ;</li><li>les piétons peuvent utiliser <b>toute la largeur</b> de la rue, et les <b>jeux sont autorisés</b> ;</li><li>tu ne peux ni mettre en danger ni gêner les piétons ; <b>au besoin, tu t'arrêtes</b> ;</li><li>tu redoubles de prudence en présence d'enfants.</li></ul><p>Exemple : en Wallonie, un C43 te permettait 70. Tu entres dans une zone de rencontre : le C43 cesse au panneau de zone et tu passes à <b>20 km/h</b>.</p>","tip":"Zone résidentielle / de rencontre = 20 km/h et les piétons sont « chez eux ».","ref":"Art. 22bis et 68 (C43) AR 01/12/1975"},{"title":"La distance de sécurité","body":"<p>Le code ne donne pas de chiffre pour les voitures : tu dois garder une <b>distance de sécurité suffisante compte tenu de ta vitesse</b>. Plus tu roules vite, plus elle doit être grande. Par temps de pluie ou de verglas, augmente-la encore.</p><p>Des chiffres précis existent pour les <b>gros véhicules</b> :</p><ul><li>Hors agglomération, véhicules de <b>plus de 7,5 tonnes</b> ou <b>plus de 7 mètres</b> de long : <b>50 mètres</b> minimum entre eux.</li><li>Hors agglomération, véhicules en <b>convoi</b> : 50 mètres minimum.</li><li>Sur les <b>ponts</b>, véhicules de plus de 7,5 tonnes : <b>15 mètres</b> minimum.</li></ul>","tip":"Conseil pratique (pas un article du code) : laisse au moins 2 secondes entre toi et la voiture devant. Compte « 1001, 1002 » quand elle passe un repère.","ref":"Art. 10.1, 2° et 18 AR 01/12/1975"}],"keypoints":["La limite est un maximum : adapte ta vitesse (météo, visibilité, enfants, chargement).","Agglomération : 50 km/h en Wallonie et Flandre, 30 km/h à Bruxelles.","Hors agglomération : 90 en Wallonie, 70 en Flandre et à Bruxelles ; 120 sur autoroute et 2×2 bandes à berme centrale.","Plus de 3,5 t sur autoroute : 90 km/h. Un C43 plus bas reste valable même sur autoroute.","C43 : valable jusqu'au prochain carrefour inclus ; zone F4a : jusqu'au F4b.","Zone 30 / abords d'école / ralentisseur : 30 km/h. Zone résidentielle ou de rencontre : 20 km/h.","Distance de sécurité suffisante selon ta vitesse ; poids lourds hors agglo : 50 m.","Animal effrayé : arrêt. Interdit de rouler anormalement lentement ou de freiner sans raison."]}};
